#!/usr/bin/env bash
# Some portions generated by Codex. Run only after behavioral validation, hit proof and CPU-window approval.
set -euo pipefail
cd "$(dirname "$0")/../../.."
: "${CP_A:?}" "${CP_B:?}" "${CP_C:?}" "${CP_D2:?}" "${LOCK:?}" "${BASELINE_SHA:?}" "${CANDIDATE_SHA:?}" "${CELLS_FILE:?Approved TSV required}" "${IDENTITIES_FILE:?Immutable six-arm source identities required}"
JAVA=${JAVA:-../toolchain/jdk-25.0.5+8/bin/java}
JAVAC=${JAVAC:-../toolchain/jdk-25.0.5+8/bin/javac}
OUT=${OUT:-experiments/threadlocal-audit/resource-restoration/matched-01}
[[ ! -e $OUT ]] || { echo "Refuse existing output $OUT" >&2; exit 2; }
mkdir -p "$OUT/harness" "$OUT/tmp"
exec 9>"$LOCK"; flock 9
"$JAVAC" -cp "$CP_D2" -d "$OUT/harness" experiments/threadlocal-audit/resource-restoration/ResourceRestorationQueryBenchmark.java
cp "$CELLS_FILE" "$OUT/cells.tsv"
cp "$IDENTITIES_FILE" "$OUT/source-identities.json"
mapfile -t FLAGS < experiments/threadlocal-audit/best-flags.txt
FLAGS+=(-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=671088640 -Drdf4j.lmdb.recordCancellation.trace=false)
printf '%s\n' "${FLAGS[@]}" > "$OUT/flags.txt"
{
 date -u; "$JAVA" -version; echo BASELINE_SOURCE="$BASELINE_SHA"; echo CANDIDATE_SOURCE="$CANDIDATE_SHA"
 echo A_RUNTIME=incumbent-combined-D-frozen; echo DEPTH_RUNTIME=selected-LmdbStoreConnection-family; echo RESOURCE_RUNTIME=selected-QueryExecutionContext-family; echo RECORD_CANCELLATION=excluded
 for arm in A B C D2; do key=CP_$arm; printf '%s=%s\n' "$key" "${!key}"; done
 sha256sum experiments/threadlocal-audit/resource-restoration/ResourceRestorationQueryBenchmark.java "$OUT/cells.tsv"
} > "$OUT/environment.txt" 2>&1
python3 - "$OUT" <<'PY'
import os,pathlib,hashlib,json,sys
out={}
for arm in ('A','B','C','D2'):
 paths=[]
 for part in os.environ['CP_'+arm].split(':'):
  p=pathlib.Path(part);files=sorted(p.rglob('*.class')) if p.is_dir() else [p]
  paths.append({'entry':part,'sha256':{str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in files}})
 out[arm]=paths
pathlib.Path(sys.argv[1],'runtime-manifest.json').write_text(json.dumps(out,indent=2))
PY
run() {
 local arm=$1 cell=$2 regime=$3 shape=$4 adjacency=$5 groups=$6 index=$7 warm=$8 iterations=$9
 local key=CP_$arm on=false; local cp=${!key}
 local log="$OUT/$cell-$index-$arm.log" fixture="$(realpath -m "$OUT/fixture-$cell")"
 local -a cmd=("$JAVA" --enable-native-access=ALL-UNNAMED -Xms2g -Xmx3g "${FLAGS[@]}"
  "-Xlog:gc:file=$log.gc.log:time,uptime,level,tags" "-Djava.io.tmpdir=$(realpath "$OUT/tmp")"
  "-Drdf4j.lmdb.recordCancellation.owned=$on" "-Daudit.regime=$regime" "-Daudit.shape=$shape"
  "-Daudit.adjacency=$adjacency" "-Doverlay.benchmark.fixture=$fixture" "-Doverlay.benchmark.warmups=$warm"
  -cp "$OUT/harness:$cp" org.eclipse.rdf4j.sail.lmdb.evaluation.ResourceRestorationQueryBenchmark "$groups" 10 "$iterations" true)
 printf '%q ' "${cmd[@]}" > "$log.command"
 "${cmd[@]}" > "$log" 2>&1
}
# TSV columns: cell_id, regime, shape, adjacency_boolean, groups. No header. Comments/empty lines ignored.
while IFS=$'\t' read -r cell regime shape adjacency groups; do
 [[ -z $cell || $cell == \#* ]] && continue
 [[ $cell =~ ^[a-z0-9_-]+$ && $groups =~ ^[1-9][0-9]*$ ]] || { echo "Invalid cell $cell" >&2; exit 2; }
 run A "$cell" "$regime" "$shape" "$adjacency" "$groups" reference 0 1
 i=0
 order=(A B D2 C B C A D2 C D2 B A D2 A C B)
 for arm in "${order[@]}"; do
  i=$((i+1)); run "$arm" "$cell" "$regime" "$shape" "$adjacency" "$groups" "$(printf '%02d' "$i")" 20 10
 done
done < "$OUT/cells.tsv"
python3 experiments/threadlocal-audit/resource-restoration/summarize-matched.py "$OUT" > "$OUT/summary.json"
